'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['readOwnPath']);
const { readOwnPath } = api;

for (const args of [
  [null, ['x']], [1, ['x']], ['text', ['x']],
  [{}, undefined], [{}, []], [{}, ['']], [{}, [1]], [{}, ['x', '']]
]) {
  assert.throws(() => readOwnPath(...args), TypeError);
}

const leaf = { retained: true };
const record = {
  a: { b: { c: leaf } },
  undefinedValue: undefined,
  nil: null,
  primitive: 3
};
const path = ['a', 'b', 'c'];
const found = readOwnPath(record, path);
assert.deepEqual(found, { found: true, value: leaf });
assert.strictEqual(found.value, leaf);
assert.deepEqual(path, ['a', 'b', 'c']);
assert.strictEqual(record.a.b.c, leaf);
assert.deepEqual(readOwnPath(record, ['undefinedValue']), { found: true, value: undefined });
assert.deepEqual(readOwnPath(record, ['missing']), { found: false, value: undefined });
assert.deepEqual(readOwnPath(record, ['nil', 'x']), { found: false, value: undefined });
assert.deepEqual(readOwnPath(record, ['primitive', 'x']), { found: false, value: undefined });

const prototype = { inherited: { value: 1 } };
const child = Object.create(prototype);
child.own = Object.create({ inheritedNested: 2 });
child.own.value = 3;
assert.deepEqual(readOwnPath(child, ['inherited']), { found: false, value: undefined });
assert.deepEqual(readOwnPath(child, ['own', 'inheritedNested']), { found: false, value: undefined });
assert.deepEqual(readOwnPath(child, ['own', 'value']), { found: true, value: 3 });

function callable() {}
callable.meta = { ready: false };
assert.deepEqual(readOwnPath(callable, ['meta', 'ready']), { found: true, value: false });

const nullPrototype = Object.create(null);
nullPrototype.x = 7;
assert.deepEqual(readOwnPath(nullPrototype, ['x']), { found: true, value: 7 });

